import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"Einträge löschen","description":"Einzelne Einträge und mehrere Einträge auf einmal löschen.","frontmatter":{"title":"Einträge löschen","description":"Einzelne Einträge und mehrere Einträge auf einmal löschen."},"headers":[],"relativePath":"grids/eintraege-loeschen.md","filePath":"grids/eintraege-loeschen.md","lastUpdated":1788108473000}'),a={name:"grids/eintraege-loeschen.md"};function s(l,e,h,d,c,o){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="eintrage-loschen" tabindex="-1">Einträge löschen <a class="header-anchor" href="#eintrage-loschen" aria-label="Permalink to &quot;Einträge löschen&quot;">​</a></h1><h2 id="einzelnen-eintrag-loschen" tabindex="-1">Einzelnen Eintrag löschen <a class="header-anchor" href="#einzelnen-eintrag-loschen" aria-label="Permalink to &quot;Einzelnen Eintrag löschen&quot;">​</a></h2><p>Über das Zeilenmenü. ApptiveGrid fragt nach: <em>Sind Sie sicher ?</em></p><h2 id="mehrere-eintrage-loschen" tabindex="-1">Mehrere Einträge löschen <a class="header-anchor" href="#mehrere-eintrage-loschen" aria-label="Permalink to &quot;Mehrere Einträge löschen&quot;">​</a></h2><ol><li>Markieren Sie die Einträge in der Tabelle.</li><li>Klicken Sie auf <strong>{Anzahl} löschen</strong>.</li><li>Bestätigen Sie im Dialog <em>{Anzahl} Einträge löschen?</em> mit <strong>Löschen</strong>.</li></ol><div class="danger custom-block"><p class="custom-block-title">Löschen ist endgültig</p><p>Gelöschte Einträge lassen sich in der Anwendung nicht wiederherstellen. Der <a href="/grids/versionsverlauf">Versionsverlauf</a> zeigt Änderungen an Feldwerten, holt aber keinen gelöschten Eintrag zurück.</p><p>Bei größeren Löschaktionen vorher einen <a href="/grids/csv-export">CSV-Export</a> ziehen.</p></div><h2 id="wenn-das-loschen-nicht-geht" tabindex="-1">Wenn das Löschen nicht geht <a class="header-anchor" href="#wenn-das-loschen-nicht-geht" aria-label="Permalink to &quot;Wenn das Löschen nicht geht&quot;">​</a></h2><blockquote><p><em>Löschen nicht möglich. Der Eintrag ist noch an einer anderen Stelle referenziert.</em></p></blockquote><p>Oder, mit Angabe des verweisenden Eintrags:</p><blockquote><p><em>Löschen nicht möglich. Der Eintrag wird noch von {Eintrag} referenziert.</em></p></blockquote><p>Der Eintrag ist über eine <a href="/grids/verknuepfungen">Verknüpfung</a> mit einem anderen Eintrag verbunden. Lösen Sie zuerst diese Verweise.</p><div class="tip custom-block"><p class="custom-block-title">Nennt die Meldung den Eintrag, gehen Sie direkt dorthin</p><p>In der zweiten Variante steht, welcher Eintrag den Verweis hält — das erspart die Suche.</p><p>Fehlt die Angabe, wechseln Sie in das verweisende Grid und filtern auf die Verknüpfungsspalte. Bei <em>Eintrag verknüpfen</em> führt ein Filter auf den betreffenden Wert direkt zu allen betroffenen Zeilen.</p><p>Diese Schutzfunktion ist gewollt — sie verhindert Verweise ins Leere.</p></div><h2 id="vorsicht-bei-gefilterten-ansichten" tabindex="-1">Vorsicht bei gefilterten Ansichten <a class="header-anchor" href="#vorsicht-bei-gefilterten-ansichten" aria-label="Permalink to &quot;Vorsicht bei gefilterten Ansichten&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Sie löschen echte Einträge, nicht Zeilen einer Ansicht</p><p>Eine Ansicht zeigt nur einen Ausschnitt. Löschen wirkt aber immer auf das <strong>Grid</strong> — der Eintrag ist danach in allen Ansichten weg.</p><p>Vergewissern Sie sich vor einer Massenlöschung, dass der Filter genau das trifft, was Sie meinen. Ein Blick auf die Anzahl im Löschdialog hilft: Steht dort eine unerwartet hohe Zahl, stimmt die Auswahl nicht.</p></div><h2 id="loschen-und-flows" tabindex="-1">Löschen und Flows <a class="header-anchor" href="#loschen-und-flows" aria-label="Permalink to &quot;Löschen und Flows&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Es gibt keinen Auslöser für gelöschte Einträge</p><p>Die verfügbaren <a href="/flows/trigger">Auslöser</a> reagieren auf neue und geänderte Einträge, nicht auf gelöschte. Ein Flow kann also nicht auf eine Löschung reagieren.</p><p>Soll etwas beim „Entfernen&quot; passieren, arbeiten Sie stattdessen mit einem Statusfeld: Setzen Sie den Eintrag auf <code>Storniert</code> statt ihn zu löschen, und lassen Sie den Flow auf diese Änderung reagieren.</p></div><h2 id="alternativen-zum-loschen" tabindex="-1">Alternativen zum Löschen <a class="header-anchor" href="#alternativen-zum-loschen" aria-label="Permalink to &quot;Alternativen zum Löschen&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Oft ist Ausblenden besser</p><table tabindex="0"><thead><tr><th>Statt zu löschen …</th><th>Vorgehen</th></tr></thead><tbody><tr><td>Alte Einträge stören die Übersicht</td><td>Ansicht filtern, etwa auf die letzten 12 Monate</td></tr><tr><td>Eintrag ist erledigt</td><td>Statusfeld auf <code>Erledigt</code>, Ansicht darauf filtern</td></tr><tr><td>Eintrag war ein Fehler</td><td>Löschen ist hier richtig</td></tr><tr><td>Daten müssen aufbewahrt werden</td><td>Nicht löschen — filtern</td></tr></tbody></table><p>Gefilterte Einträge zählen weiterhin gegen die <a href="/grids/eintraege#grenzen">tarifabhängige Zahl an Einträgen je Grid</a>. Wenn es darum geht, ist Löschen der einzige Weg — dann aber mit vorherigem Export.</p></div><h2 id="grid-statt-eintrage-loschen" tabindex="-1">Grid statt Einträge löschen <a class="header-anchor" href="#grid-statt-eintrage-loschen" aria-label="Permalink to &quot;Grid statt Einträge löschen&quot;">​</a></h2><p>Soll der gesamte Datenbestand weg, ist das Löschen des Grids der direktere Weg. Prüfen Sie vorher, ob Ansichten, Formulare, Flows oder <a href="/seiten/was-sind-seiten">Seiten</a> darauf zugreifen.</p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/grids/eintraege">Einträge anlegen und bearbeiten</a></li><li><a href="/grids/versionsverlauf">Versionsverlauf</a></li><li><a href="/grids/csv-export">CSV-Export</a></li></ul>',22)])])}const f=n(a,[["render",s]]);export{u as __pageData,f as default};
